<?php declare(strict_types=1);
$movementAccount=input($_POST,'account',$accountId);$movementAccounts=$finance->paymentAccounts();
$bankLedgerText??=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\BankLedgerMessages::text($source,[],$values); ?>
<div class="content"><form method="post" class="card transaction-new"><?= csrf().hidden('action','create-transaction').hidden('request_key',input($_POST,'request_key',bin2hex(random_bytes(16)))) ?><h2><?= e($bankLedgerText('Kontoumsatz erfassen')) ?></h2><p class="muted"><?= e($bankLedgerText('Einen bereits erfolgten Geldfluss erfassen. Dieser Umsatz verändert den angezeigten Kontostand. Vorhandene Umsätze in der Liste öffnen, um sie zuzuordnen.')) ?></p><p class="muted" data-cash-transfer-help><?= e($bankLedgerText('Bargeldeinzahlungen und Abhebungen über die beiden tatsächlichen Gegenumsätze als eigenen Geldtransfer zuordnen.')) ?></p><div class="form-grid"><label><?= e($bankLedgerText('Konto / Kasse')) ?><select class="form-control" name="account" required><?php if($movementAccount===''||!in_array($movementAccount,array_column($movementAccounts,'id'),true)): ?><option value="<?= e($movementAccount) ?>" selected><?= e($bankLedgerText($movementAccount===''?'Konto oder Kasse ausdrücklich auswählen':'Gewähltes Konto derzeit nicht verfügbar – Auswahl prüfen')) ?></option><?php endif ?><?php foreach($movementAccounts as $a): ?><option value="<?= e($a['id']) ?>" <?= $movementAccount===$a['id']?'selected':'' ?>><?= e($a['name']) ?></option><?php endforeach ?></select></label><label><?= e($bankLedgerText('Zahlungsrichtung')) ?><select class="form-control" name="direction"><option value="income"><?= e($bankLedgerText('Zahlungseingang')) ?></option><option value="expense" <?= input($_POST,'direction')==='expense'?'selected':'' ?>><?= e($bankLedgerText('Zahlungsausgang')) ?></option></select></label><label><?= e($bankLedgerText('Betrag (EUR)')) ?><input class="form-control" name="amount" required inputmode="decimal" value="<?= e(input($_POST,'amount')) ?>"></label><label><?= e($bankLedgerText('Buchungsdatum')) ?><input class="form-control" name="booked_on" type="date" required max="<?= date('Y-m-d') ?>" value="<?= e(input($_POST,'booked_on',date('Y-m-d'))) ?>"></label><label class="wide"><?= e($bankLedgerText('Name / Geschäftspartner')) ?><input class="form-control" name="counterparty" list="transaction-counterparties" autocomplete="off" placeholder="<?= e($bankLedgerText('Mitglied / Kontakt suchen oder Namen eingeben')) ?>" maxlength="200" value="<?= e(input($_POST,'counterparty')) ?>"></label><datalist id="transaction-counterparties"><?php foreach($finance->counterparties() as $party): ?><option value="<?= e($party['name']) ?>" label="<?= e($bankLedgerText($party['is_member']?'Mitglied':'Kontakt')) ?>"></option><?php endforeach ?></datalist><label class="wide"><?= e($bankLedgerText('Verwendungszweck')) ?><input class="form-control" name="description" required maxlength="500" value="<?= e(input($_POST,'description')) ?>"></label></div><div class="actions"><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'finance','tab'=>'bank','account'=>$accountId])) ?>"><?= e($bankLedgerText('Abbrechen')) ?></a><button class="btn btn-solid theme-primary"><?= e($bankLedgerText('Kontoumsatz speichern')) ?></button></div></form></div>
